using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Security.Cryptography;
namespace Musikbox {
 public sealed class FileTagAction {
  sealed class Entry {public string Before,After,OldCopy,NewCopy,OldHash,NewHash;public Dictionary<string,string> OldTags,NewTags;}
  readonly List<Entry> entries=new List<Entry>();public readonly string Id=Guid.NewGuid().ToString("N");bool applied,commitAttempted;
  static string Hash(string path){using(var file=File.OpenRead(path))using(var hash=SHA256.Create())return BitConverter.ToString(hash.ComputeHash(file));}
  public static FileTagAction Apply(IList<TagChange> changes,string backupRoot,Action check=null){TagConversion.Validate(changes);var action=new FileTagAction();string root=Path.Combine(backupRoot,action.Id);Directory.CreateDirectory(root);try{for(int i=0;i<changes.Count;i++){if(check!=null)check();var c=changes[i];if(String.Equals(c.Source,c.Target,StringComparison.OrdinalIgnoreCase)&&c.ArtworkPath==null){var existing=TagFields.Read(c.Source);var previous=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(var field in c.Fields)previous[field.Key]=existing.ContainsKey(field.Key)?existing[field.Key]:"";TagFields.Write(c.Source,c.Fields);TagFields.Verify(c.Source,c.Fields);action.entries.Add(new Entry{Before=c.Source,After=c.Target,OldTags=previous,NewTags=new Dictionary<string,string>(c.Fields,StringComparer.OrdinalIgnoreCase)});continue;}string old=Path.Combine(root,i+"-vorher"+Path.GetExtension(c.Source)),next=Path.Combine(root,i+"-nachher"+Path.GetExtension(c.Source));File.Copy(c.Source,old);File.Copy(c.Source,next);if(c.Fields.Count>0){TagFields.Write(next,c.Fields);TagFields.Verify(next,c.Fields);}if(c.ArtworkPath!=null)EmbeddedArtwork.Write(next,c.ArtworkPath,c.AppendArtwork);action.entries.Add(new Entry{Before=c.Source,After=c.Target,OldCopy=old,NewCopy=next,OldHash=Hash(old),NewHash=Hash(next)});}if(check!=null)check();action.commitAttempted=true;action.Restore(true);foreach(var c in changes){c.Song.Source=c.Target;if(c.Song.PendingTags!=null)foreach(string key in c.Fields.Keys)c.Song.PendingTags.Remove(key);if(c.ArtworkPath!=null)c.Song.Artwork=null;var read=MediaMetadata.Read(c.Target);c.Song.Artist=read.Artist;c.Song.Title=read.Title;c.Song.Album=read.Album;if(c.Fields.ContainsKey("album"))c.Song.AlbumOverride=true;c.Song.Year=read.Year;c.Song.Genre=read.Genre;c.Song.Comment=read.Comment;c.Song.Track=read.Track;c.Song.AcoustidId=read.AcoustidId;c.Song.Bitrate=read.Bitrate;c.Song.TagType=read.TagType;c.Song.PreparedSource=c.Song.PreparedProfile=null;if(c.Song.PendingTags!=null)foreach(var pending in c.Song.PendingTags){switch(pending.Key){case "artist":c.Song.Artist=pending.Value;break;case "title":c.Song.Title=pending.Value;break;case "album":c.Song.Album=pending.Value;break;case "year":c.Song.Year=pending.Value;break;case "genre":c.Song.Genre=pending.Value;break;case "track":c.Song.Track=pending.Value;break;case "comment":c.Song.Comment=pending.Value;break;case "acoustid_id":c.Song.AcoustidId=pending.Value;break;}}}return action;}catch{if(!action.applied&&!action.commitAttempted)try{Directory.Delete(root,true);}catch{}throw;}}
  public void Restore(bool forward){foreach(var e in entries){if(e.OldTags!=null)continue;string current=forward?e.Before:e.After,target=forward?e.After:e.Before,hash=forward?e.OldHash:e.NewHash;if(!File.Exists(current)||Hash(current)!=hash)throw new IOException("Datei wurde außerhalb dieser Aktion verändert. Wiederherstellung abgebrochen: "+current);if(!String.Equals(current,target,StringComparison.OrdinalIgnoreCase)&&File.Exists(target))throw new IOException("Ziel bereits vorhanden: "+target);}
   int done=0;try{foreach(var e in entries){if(e.OldTags!=null){TagFields.Write(e.Before,forward?e.NewTags:e.OldTags);done++;continue;}string current=forward?e.Before:e.After,target=forward?e.After:e.Before,copy=forward?e.NewCopy:e.OldCopy;Replace(current,target,copy);done++;}applied=forward;}catch{foreach(var e in entries.Take(done).Reverse()){if(e.OldTags!=null)TagFields.Write(e.Before,forward?e.OldTags:e.NewTags);else Replace(forward?e.After:e.Before,forward?e.Before:e.After,forward?e.OldCopy:e.NewCopy);}throw;}}
  static void Replace(string current,string target,string copy){string temp=current+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.Copy(copy,temp);if(String.Equals(current,target,StringComparison.Ordinal))File.Replace(temp,current,null);else{File.Move(current,target);try{File.Replace(temp,target,null);}catch{File.Move(target,current);throw;}}}finally{if(File.Exists(temp))File.Delete(temp);}}
 }
}
